func _cal() -> void:
	var rows := [["Двуручный топор", 2, 4, "pine", 1950.0], ["Кирка", 4, 5, "granite", 300.0],
		["Кирка", 4, 4, "granite", 110.0], ["Кирка", 4, 1, "granite", 66.0]]
	for r in rows:
		var t := Tools.make(int(r[1]), int(r[2]), Physique.DEFAULT)
		var e := Impact.energy(t, Physique.at(Physique.DEFAULT), 1.0)
		var w := float(Impact.blow(t, String(r[3]), e).wear)
		var n := 0.5 * Impact.reserve(t) / w
		print("WEAR_CAL %s %s on %s: E=%.0f J, %.0f blows to sharpness 0.5 (want %.0f)" % [
			r[0], Tools.MATERIALS[int(r[2])].id, r[3], e, n, float(r[4])])
		_check("cal %s/%s" % [r[0], r[3]], absf(n / float(r[4]) - 1.0) <= TOL, "%.0f vs %.0f" % [n, float(r[4])])
	var k := Tools.make(3, 4, Physique.DEFAULT)                       # the felling axe: 56 blows a 30 cm pine (tech counts)
	var ek := Impact.energy(k, Physique.at(Physique.DEFAULT), 1.0)
	var pines := 0.5 * Impact.reserve(k) / float(Impact.blow(k, "pine", ek).wear) / 56.0
	print("WEAR_CAL felling axe: %.1f pines to sharpness 0.5 (told: ~30)" % pines)
	_check("cal ~30 pines", pines > 24.0 and pines < 38.0, "%.1f" % pines)


func _law() -> void:
	var pick := Tools.make(4, 5, Physique.DEFAULT)
	var axe := Tools.make(2, 4, Physique.DEFAULT)
	var one: Dictionary = pick.duplicate()
	one.sharp = 1.0
	var same := true
	for m in ["granite", "sandstone", "limestone", "pine", "soil"]:
