			same = same and var_to_str(Impact.blow(t[0], m, 150.0)) == var_to_str(Impact.blow(t[1], m, 150.0))
			same = same and var_to_str(Impact.rock(t[0], 150.0, "granite")) == var_to_str(Impact.rock(t[1], 150.0, "granite"))
			same = same and Impact.half_angle(t[0]) == Impact.half_angle(t[1])
			same = same and var_to_str(Impact.wood(t[0], 150.0, "pine")) == var_to_str(Impact.wood(t[1], 150.0, "pine"))
	_check("sharp 1.0 == W1 numbers", same)
