		"%.1f -> %.1f deg" % [rad_to_deg(Impact.half_angle(axe)), rad_to_deg(Impact.half_angle(dull))])
	_check("dull bites shallower", float(Impact.wood(dull, 150.0, "pine").depth) < float(Impact.wood(axe, 150.0, "pine").depth))
	var pd: Dictionary = pick.merged({sharp = 0.5})
	_check("dull point bigger", float(Impact.rock(pd, 150.0, "granite").tip) > float(Impact.rock(pick, 150.0, "granite").tip))
