	var bt := Impact.body_tool(10.0, 0.1, "granite")
	var bl := Impact.blow(bt, "granite", 98.0)
	_check("body_tool gate works", bool(bl.bites) and float(bl.share) > 0.99 and float(bl.vol) > 0.0, str(bl.share))


